<style lang="scss" src="./gms-send-report-modal.scss"></style>

<script>
import { MountingPortal } from "portal-vue";
import { Component, Prop, Watch, Vue } from "vue-property-decorator";
import {
  destroyModalRootContent,
  ensureModalRoot,
} from "../../util/ensure-modal-root";
import Button from "../button/button";
import { ButtonMode, ButtonSize } from "../button/button.constants";
import Icon from "../icon/icon";
import { IconShape } from "../icon/icon.constants";
import Modal from "../../components/modal/modal";
import { ModalWidth } from "../modal/modal.constants";
import ScrollView from "../scroll-view/scroll-view";
import Select from "../select/select";
import SelectionMenu from "../selection-menu/selection-menu";
import { SelectionMenuMode } from "../selection-menu/selection-menu.constants";

const Pages = {
  ONCE: "once",
  SCHEDULE: "schedule",
};

const Hours = [];
for (let i = 1; i <= 12; i++) {
  Hours.push(i);
}
Hours.unshift(Hours.pop());
const HourOptions = Hours.map((v) => {
  return { label: v.toString(), value: v };
});

const Minutes = [];
for (let i = 0; i < 60; i++) {
  Minutes.push(i);
}

const MinuteOptions = Minutes.map((v) => {
  const minStr = v.toString();
  return { label: minStr.length < 2 ? `0${minStr}` : minStr, value: v };
});

const getDate = (scheduleDate) => {
  const date = scheduleDate ? new Date(scheduleDate) : new Date();
  let dateString = date.toISOString();
  dateString = dateString.slice(0, dateString.indexOf('T'));

  return {
    isAM: date.getHours() < 12,
    currentHour: (date.getHours() + 24) % 12 || 12,
    currentMinute: date.getMinutes(),
    dateString
  };
};

const WeekdayOptions = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];

@Component({
  components: {
    Icon,
    Button,
    Modal,
    MountingPortal,
    Select,
    SelectionMenu,
    ScrollView,
  },
})
export default class GmsSendMessageModal extends Vue {
  /**
   * This is an error message to display to the user. You can set this in
   * response to the schedule event for validation purposes.
   */
  @Prop({ type: String }) error;

  /***
   * This is a status message to display to the user. You can use this
   * to update users on the status of a successful export.
   */
  @Prop({ type: String }) status;

  /**
   * Configures the dropdown for selecting the file type to send the report as.
   */
  @Prop({ type: Object, default: () => ({ placeholder: "", options: [] }) })
  fileTypeConfig;

  /**
   * Configures the dropdown for selecting the frequency the report is sent.
   */
  @Prop({ type: Object, default: () => ({ placeholder: "", options: [] }) })
  frequencyConfig;

  /**
   * The list of emails the user is sharing their email with. This list should
   * be updated everytime the user clicks the invite button.
   *
   * [
   *   title: string;
   *   email: string;
   * ]
   */
  @Prop({ type: Array, default: () => [] })
  emailInvitations;

  @Prop({ type: Boolean, default: false })
  showSendMessage;

  @Prop({ type: Object, default: () => ({}) })
  schedule;

  @Watch("schedule")
  onScheduleChange() {
    this.repopulateSchedule();
  }

  /**
   * This is the root modal element the menu resides in to render floating above
   * all the other elements in the DOM.
   */
  modalRoot = null;
  /** Currentl selected page */
  page = Pages.ONCE;

  sendInvitationValue = "";
  fileTypeValue = "";

  HourOptions = HourOptions;
  MinuteOptions = MinuteOptions;
  WeekOptions = WeekdayOptions.map((o) => ({
    label: o.charAt(0),
    value: o.toUpperCase(),
  }));

  currentFrequency = "DAILY";
  // weekly
  currentWeekOption = "MONDAY";
  // monthly
  date;
  minDate;
  // time
  hour = 0;
  minute = 0;
  isAM = true;

  // Enums
  IconShape = IconShape;
  ButtonMode = ButtonMode;
  ButtonSize = ButtonSize;
  ModalWidth = ModalWidth;
  SelectionMenuMode = SelectionMenuMode;
  Pages = Pages;

  showScheduleDeleteConfirmation = false;
  // This is used to reset schedule when
  // closing/cancelling the dialog
  currentSchedule = {};

  handleDailyFrequencyChange(value) {
    this.dailyFrequency = value;
  }

  handleHourChange(value) {
    this.hour = value;
  }

  handleMinuteChange(value) {
    this.minute = value;
  }

  handleAmPmChange(value) {
    this.isAM = value === 0;
  }

  beforeMount() {
    // HACK: MountingPortal spawns mass duplicates. So as Thanos once said:
    //       Fine. I'll do it myself
    destroyModalRootContent("Menu");
    this.modalRoot = ensureModalRoot();

    if (!this.modalRoot) {
      console.warn("Could not establish modal root for floating componentry");
      return;
    }

    window.addEventListener("resize", this.handleResize);

    // set current time as the default selected time to send the report
    const { currentHour, currentMinute, isAM, dateString } = getDate();
    this.hour = currentHour;
    this.minute = currentMinute;
    this.isAM = isAM;

    this.date = dateString;
    // set initial monthly frequency using current date
    this.minDate = dateString;

    // if schedule exists, set values appropriately
    this.repopulateSchedule();
  }

  beforeDestroy() {
    window.removeEventListener("resize", this.handleResize);
  }

  handleResize() {
    this.$forceUpdate();
  }

  /**
   * HACKY HACKS: Due to vue portal having it's own set of issues and we handle
   * its DOM disposal manually, this causes certain scenarios to throw errors
   * from the MountingPortal component. So, we just absorb those issues here for
   * now until better solutions can be discovered or Vue3 is used with better
   * native made portals.
   */
  errorCaptured(_err, _vm, info) {
    if (info === "beforeDestroy hook") {
      return false;
    }
  }

  get modalRootId() {
    return `#${this.modalRoot.id}`;
  }

  get containerStyle() {
    return {
      height: `${window.innerHeight}px`,
    };
  }

  handleCloseOutside(e) {
    if (e.target !== this.$refs.container) return;
    this.handleClose();
    e.stopPropagation();
    e.preventDefault();
  }

  handleClose() {
    this.page = Pages.ONCE;
    this.repopulateSchedule();

    /**
     * Emits when the user intends to close this modal
     *
     * @event close
     */
    this.$emit("close");
  }

  handleTab(page) {
    this.page = page;
  }

  handleFileTypeChange(value) {
    this.fileTypeValue = value;
  }

  handleAddEmail() {
    /**
     * Emits when the user clicks to add the email or name they entered into the
     * input.
     *
     * @event addEmail
     */
    const emailAddress = this.sendInvitationValue;
    this.$emit("addEmail", emailAddress);
    this.sendInvitationValue = "";
  }

  handleRemoveEmail(i) {
    this.$emit("removeEmail", i);
  }

  handleInvite() {
    const [year, month, day] = this.date.split("-").map((num) => Number(num));
    /**
     * Emits when the user clicks to send the report to an individual or
     * multiple individuals. The passed argument contains
     *
     * @event send
     */
    this.$emit("send", {
      pageMode: this.page,
      id: this.schedule.id,
      frequencyMode: this.currentFrequency,
      weekOption: this.currentWeekOption,
      sendAt: this.generateTimeString(),
      fileType: this.fileTypeValue,
      monthlyFrequency: {
        year,
        month,
        day,
      },
    });
  }

  handleSendOnce() {
    /**
     * Emits when the user clicks to send the report as a one-time event
     *
     * @event sendOnce
     */
    this.$emit("sendOnce", {
      pageMode: this.page,
      emails: this.sendInvitationValue,
      fileType: this.fileTypeValue,
    });
  }

  handleFrequencyChange(value) {
    this.currentFrequency = value;
  }

  handleChangeWeekOption(index, value) {
    this.currentWeekOption = value;
  }

  handleDeleteSchedule() {
    this.$emit("deleteSchedule");
    this.showScheduleDeleteConfirmation = false;
  }

  // This should be temporary until we get a proper
  // time selector component.
  generateTimeString() {
    // 12:30 AM should be 00:30, 12:30 PM should be 12:30 in 24-hour format.
    const hourString = `${this.isAM ? (this.hour % 12) : (this.hour % 12) + 12}`.padStart(
      2,
      "0"
    );
    const minString = `${this.minute}`.padStart(2, "0");
    return `${hourString}:${minString}:00`;
  }

  handleDatePick(date) {
    this.date = date;
  }

  repopulateSchedule() {
    if (!this.schedule.frequency) {
      return;
    }

    this.currentFrequency = this.schedule.frequency;
    if (this.currentFrequency === "WEEKLY") {
      this.currentWeekOption = this.schedule.weeklyOn[0];
    } else if (this.currentFrequency === "MONTHLY") {
      // date?
      const { dateString } = getDate(this.schedule.nextReport);
      this.date = dateString;
    }

    const sendAt = getDate(`1970-01-01T${this.schedule.sendAt}`);
    this.hour = sendAt.currentHour;
    this.minute = sendAt.currentMinute;
    this.isAM = sendAt.isAM;

    this.fileTypeValue = this.schedule.sendAs;
  }
}
</script>

<template>
  <MountingPortal :mountTo="modalRootId" append>
    <div
      class="GmsSendReportModal"
      :style="containerStyle"
      ref="container"
      v-if="showSendMessage"
      @click="handleCloseOutside"
    >
      <div class="GmsSendReportModal__Content">
        <div class="GmsSendReportModal__Top">
          <div class="GmsSendReportModal__Left">
            <h2>Send Report</h2>
            <h3 class="error" v-if="error">{{ error }}</h3>
            <h3 class="message" v-if="status">{{ status }}</h3>
          </div>
          <div class="GmsSendReportModal__Tabs">
            <h2
              :class="[
                { 'GmsSendReportModal--active-tab': page === Pages.ONCE },
              ]"
              @click="handleTab(Pages.ONCE)"
            >
              Send Once
            </h2>
            <h2
              :class="[
                { 'GmsSendReportModal--active-tab': page === Pages.SCHEDULE },
              ]"
              @click="handleTab(Pages.SCHEDULE)"
            >
              Schedule
            </h2>
          </div>
          <div class="GmsSendReportModal__TopRight">
            <Icon
              class="GmsSendReportModal__Close"
              :shape="IconShape.CLOSE"
              :size="24"
              @click="handleClose"
            />
          </div>
        </div>

        <!-- PAGE: ONCE -->
        <div v-if="page === Pages.ONCE" class="GmsSendReportModal__Center">
          <div class="GmsSendReportModal__Share">
            <hr />
            <div class="GmsSendReportModal__Row">
              <h2>Send As</h2>
              <Select
                key="file-type"
                class="GmsSendReportModal__FileType"
                :label="fileTypeConfig.placeholder"
                :value="fileTypeValue"
                :items="fileTypeConfig.options"
                @select="handleFileTypeChange"
              />
              <input
                class="GmsSendReportModal__Input"
                type="text"
                placeholder="Type Emails..."
                v-model="sendInvitationValue"
              />
              <Button
                class="GmsSendReportModal__Next"
                :mode="ButtonMode.PRIMARY"
                :label="'Send'"
                @click="handleSendOnce"
              />
            </div>
          </div>
        </div>

        <!-- PAGE: SCHEDULE -->
        <div
          v-if="page === Pages.SCHEDULE"
          class="GmsSendReportModal__LargeCenter"
        >
          <div class="GmsSendReportModal__Share GmsSendReportModal--schedule">
            <hr />
            <div class="GmsSendReportModal__Row">
              <input
                class="GmsSendReportModal__Input"
                type="text"
                placeholder="Type Emails..."
                v-model="sendInvitationValue"
              />
              <Button
                class="GmsSendReportModal__Next"
                :mode="ButtonMode.PRIMARY"
                :label="'Add'"
                @click="handleAddEmail"
              />
            </div>
            <h2 v-if="emailInvitations.length > 0">
              Scheduled to send to
            </h2>
            <ScrollView>
              <div
                class="GmsSendReportModal__Email"
                v-for="(email, i) in emailInvitations"
                :key="i"
              >
                <button
                  class="GmsSendReportModal__Subscriber-Row-Delete"
                  @click="handleRemoveEmail(i)"
                  aria-label="Remove Subscriber"
                >
                  <Icon :shape="IconShape.CLOSE" :size="24" />
                </button>
                <div class="GmsSendReportModal__EmailRecipient">
                  <h2>{{ email.title }}</h2>
                  <h3>{{ email.email }}</h3>
                </div>
              </div>
            </ScrollView>
          </div>
          <div class="GmsSendReportModal__Frequency">
            <div class="GmsSendReportModal__Row">
              <h2>Frequency</h2>
              <Select
                key="frequency"
                class="GmsSendReportModal__FrequencySelect"
                :label="frequencyConfig.placeholder"
                :value="currentFrequency"
                :items="frequencyConfig.options"
                @select="handleFrequencyChange"
              />
              <div
                class="GmsSendReportModal__FrequencyOptions"
                v-if="this.currentFrequency === 'WEEKLY'"
              >
                <h2>On</h2>
                <div
                  v-for="(option, index) of WeekOptions"
                  :key="index"
                  :class="[
                    'GmsSendReportModal__WeekOption',
                    option.value === currentWeekOption
                      ? 'GmsSendReportModal--Selected'
                      : 'GmsSendReportModal--Unselected',
                  ]"
                  @click="handleChangeWeekOption(index, option.value)"
                >
                  {{ option.label }}
                </div>
              </div>
              <div
                class="GmsSendReportModal__FrequencyOptions"
                v-else-if="this.currentFrequency === 'MONTHLY'"
              >
                <h2>{{ this.schedule.id ? "Next Run" : "starting on" }}</h2>
                <input
                  class="GmsSendReportModal__DatePicker"
                  type="date"
                  placeholder="Enter a value here"
                  :value="date"
                  :min="minDate"
                  @change="handleDatePick($event.target.value)"
                />
              </div>
            </div>
            <div class="GmsSendReportModal__Row">
              <h4>Send at</h4>
              <Select
                key="hour"
                class="GmsSendReportModal__TimeSelect"
                label="HH"
                :triggerStyle="
                  () => ({
                    arrowIcon: {
                      show: false,
                    },
                  })
                "
                :value="hour"
                :items="HourOptions"
                @select="handleHourChange"
              />
              <h5>:</h5>
              <Select
                key="minute"
                class="GmsSendReportModal__TimeSelect"
                label="MM"
                :triggerStyle="
                  () => ({
                    arrowIcon: {
                      show: false,
                    },
                  })
                "
                :value="minute"
                :items="MinuteOptions"
                @select="handleMinuteChange"
              />
              <Select
                key="am_pm"
                class="GmsSendReportModal__AmPmSelect"
                label="AM"
                :triggerStyle="
                  () => ({
                    arrowIcon: {
                      show: false,
                    },
                  })
                "
                :value="isAM ? 0 : 1"
                :items="[
                  { label: 'AM', value: 0 },
                  { label: 'PM', value: 1 },
                ]"
                @select="handleAmPmChange"
              />
              <h6>Send as</h6>
              <Select
                key="fileType"
                class="GmsSendReportModal__FrequencySelect"
                :label="fileTypeConfig.placeholder"
                :value="fileTypeValue"
                :items="fileTypeConfig.options"
                @select="handleFileTypeChange"
              />
            </div>
          </div>
        </div>
        <div
          v-if="page === Pages.ONCE"
          class="GmsSendReportModal__LargeBottom"
        ></div>

        <div v-if="page === Pages.SCHEDULE" class="GmsSendReportModal__Bottom">
          <div class="GmsSendReportModal__BottomLeft">
             <Button
              v-if="schedule.id"
              :size="ButtonSize.SMALL"
              label="Delete Schedule"
              labelColor="red"
              :mode="ButtonMode.TEXT"
              :icon="IconShape.TRASH"
              :iconSize="16"
              iconColor="red"
              @click="showScheduleDeleteConfirmation = true"
            />
          </div>
          <div class="GmsSendReportModal__BottomRight">
            <Button
              :mode="ButtonMode.GMS_ICON"
              :size="ButtonSize.SMALL"
              :label="'Cancel'"
              @click="handleClose"
            />
            <Button
              class="GmsSendReportModal__Next"
              :mode="ButtonMode.PRIMARY"
              :size="ButtonSize.SMALL"
              :label="schedule.id ? 'Update Schedule' : 'Schedule Report'"
              @click="handleInvite"
            />
          </div>
        </div>
      </div>
      <!-- Delete Schedule Confirmation Modal -->
      <Modal
        v-if="showScheduleDeleteConfirmation"
        @close="showScheduleDeleteConfirmation = false"
        title="Delete Schedule"
      >
        <p class="GmsSendReportModal__ConfirmationText">
          Are you sure you want to delete this schedule?
        </p>
        <template v-slot:modal-footer-right>
          <Button
            :size="ButtonSize.SMALL"
            label="Delete Schedule"
            backgroundColor="red"
            labelColor="white"
            :mode="ButtonMode.PRIMARY"
            :icon="IconShape.TRASH"
            iconColor="white"
            :iconSize="16"
            @click="handleDeleteSchedule"
          />
          <Button
            :size="ButtonSize.SMALL"
            label="Cancel"
            @click="showScheduleDeleteConfirmation = false"
            :mode="ButtonMode.SUBTLE"
          />
        </template>
      </Modal>
    </div>
  </MountingPortal>
</template>
